
% Homework 4 Problem 4

% Part (b)
% Read pepper-noise image
g_pepper = imread('HW4Q4_pepper_image.jpg');

% Convert RGB to grayscale if needed
if ndims(g_pepper) == 3
    g_pepper = 0.2989*g_pepper(:,:,1) + ...
               0.5870*g_pepper(:,:,2) + ...
               0.1140*g_pepper(:,:,3);
end

% Convert to double in range [0,1]
g_pepper = double(g_pepper) / 255;

% Filter order for pepper noise
Q = 1.5;

% Apply 3 x 3 contraharmonic mean filter
fhat_pepper = contraharmonic_filter(g_pepper, Q);

% Display result
figure; %[output:4be547d4]

subplot(1,2,1); %[output:4be547d4]
imshow(g_pepper, []); %[output:4be547d4]
title('Original Image.jpg'); %[output:4be547d4]

subplot(1,2,2); %[output:4be547d4]
imshow(fhat_pepper, []); %[output:4be547d4]
title('Contraharmonic Filter, Q = 1.5'); %[output:4be547d4]


% Part (c)

% Read salt-noise image
g_salt = imread('HW4Q4_salt_image.jpg');

% Convert RGB to grayscale if needed
if ndims(g_salt) == 3
    g_salt = 0.2989*g_salt(:,:,1) + ...
             0.5870*g_salt(:,:,2) + ...
             0.1140*g_salt(:,:,3);
end

% Convert to double in range [0,1]
g_salt = double(g_salt) / 255;

% Filter order for salt noise
Q = -1.5;

% Apply 3 x 3 contraharmonic mean filter
fhat_salt = contraharmonic_filter(g_salt, Q);

% Display result
figure; %[output:1fc65cb8]

subplot(1,2,1); %[output:1fc65cb8]
imshow(g_salt, []); %[output:1fc65cb8]
title('Original Image.jpg'); %[output:1fc65cb8]

subplot(1,2,2); %[output:1fc65cb8]
imshow(fhat_salt, []); %[output:1fc65cb8]
title('Contraharmonic Filter, Q = -1.5'); %[output:1fc65cb8]


%% --------------- Local Function ----------------

function fhat = contraharmonic_filter(g, Q)

    [M, N] = size(g);

    % Zero padding
    g_pad = zeros(M+2, N+2);
    g_pad(2:M+1, 2:N+1) = g;

    % Initialize output image
    fhat = zeros(M, N);

    % Small epsilon prevents division by zero when Q is negative
    epsilon = 1e-10;

    for i = 1:M
        for j = 1:N

            % Extract 3 x 3 neighborhood
            neighborhood = g_pad(i:i+2, j:j+2);

            % Add epsilon only to avoid 0 raised to a negative power
            neighborhood = neighborhood + epsilon;

            % Contraharmonic mean formula
            numerator = sum(neighborhood(:).^(Q + 1));
            denominator = sum(neighborhood(:).^Q);

            fhat(i,j) = numerator / denominator;

        end
    end
end


